import time
import pandas as pd
import requests


# =========================================================
# CONFIGURATION
# =========================================================

# Path to the evaluation dataset.
DATASET_PATH = "data/reasoning_dataset.csv"

# FastAPI generation endpoint.
API_URL = "http://127.0.0.1:8000/generate"

# Maximum number of rows to benchmark.
# Start with 5 so we can verify everything first.
NUM_ROWS = 5

# Maximum time allowed for one API request.
REQUEST_TIMEOUT = 120

# Maximum tokens generated by the model.
MAX_NEW_TOKENS = 256

# Where benchmark results will be saved.
OUTPUT_PATH = "data/api_benchmark_results.csv"


# =========================================================
# LOAD DATASET
# =========================================================

print("=" * 60)
print("DATASET API BENCHMARK")
print("=" * 60)

print(f"Loading dataset: {DATASET_PATH}")

df = pd.read_csv(DATASET_PATH)

print(f"Total dataset rows: {len(df)}")


# Make sure the required column exists.
if "question" not in df.columns:
    raise ValueError(
        "Dataset must contain a 'question' column."
    )


# Take only the first NUM_ROWS for the initial test.
benchmark_df = df.head(NUM_ROWS).copy()

print(
    f"Rows selected for benchmark: "
    f"{len(benchmark_df)}"
)

print()


# =========================================================
# RUN API BENCHMARK
# =========================================================

results = []


for index, row in benchmark_df.iterrows():

    question_id = row["id"]

    question = row["question"]

    print(
        f"Running request "
        f"{index + 1}/{len(benchmark_df)} "
        f"(ID: {question_id})..."
    )

    # -----------------------------------------------------
    # Build API request
    # -----------------------------------------------------

    payload = {
        "instruction": (
            "Solve the following reasoning problem."
        ),
        "input": question,
        "max_new_tokens": MAX_NEW_TOKENS,
    }

    # -----------------------------------------------------
    # Measure complete HTTP request latency
    # -----------------------------------------------------

    start_time = time.perf_counter()

    try:

        response = requests.post(
            API_URL,
            json=payload,
            timeout=REQUEST_TIMEOUT,
        )

        end_time = time.perf_counter()

        latency_ms = (
            end_time - start_time
        ) * 1000

        # -------------------------------------------------
        # Extract generated response
        # -------------------------------------------------

        if response.status_code == 200:

            successful = True

            response_json = response.json()

            generated_response = response_json.get(
                "response",
                "",
            )

            print(
                f"Latency: "
                f"{latency_ms:.2f} ms"
            )

        else:

            successful = False

            generated_response = ""

            print(
                f"Request failed: "
                f"HTTP {response.status_code}"
            )

    except requests.RequestException as exc:

        end_time = time.perf_counter()

        latency_ms = (
            end_time - start_time
        ) * 1000

        successful = False

        generated_response = ""

        print(
            f"Request failed: {exc}"
        )

    # -----------------------------------------------------
    # Store result
    # -----------------------------------------------------

    results.append(
        {
            "id": question_id,
            "category": row.get(
                "category",
                "",
            ),
            "difficulty": row.get(
                "difficulty",
                "",
            ),
            "reasoning_type": row.get(
                "reasoning_type",
                "",
            ),
            "question": question,
            "expected_answer": row.get(
                "expected_answer",
                "",
            ),
            "model_response": generated_response,
            "latency_ms": latency_ms,
            "status_code": response.status_code
            if "response" in locals()
            else None,
            "successful": successful,
        }
    )


# =========================================================
# CREATE RESULTS DATAFRAME
# =========================================================

results_df = pd.DataFrame(results)


# =========================================================
# SAVE RESULTS
# =========================================================

results_df.to_csv(
    OUTPUT_PATH,
    index=False,
)

print()
print(
    f"Results saved to: {OUTPUT_PATH}"
)


# =========================================================
# CALCULATE LATENCY METRICS
# =========================================================

successful_latencies = results_df.loc[
    results_df["successful"],
    "latency_ms",
]


if len(successful_latencies) > 0:

    print()
    print("=" * 60)
    print("DATASET API BENCHMARK RESULTS")
    print("=" * 60)

    print(
        f"Requests:       {len(results_df)}"
    )

    print(
        f"Successful:     "
        f"{results_df['successful'].sum()}"
    )

    print(
        f"Failed:         "
        f"{(~results_df['successful']).sum()}"
    )

    print(
        f"Mean latency:   "
        f"{successful_latencies.mean():.2f} ms"
    )

    print(
        f"P50 latency:    "
        f"{successful_latencies.quantile(0.50):.2f} ms"
    )

    print(
        f"P95 latency:    "
        f"{successful_latencies.quantile(0.95):.2f} ms"
    )

    print(
        f"P99 latency:    "
        f"{successful_latencies.quantile(0.99):.2f} ms"
    )

    print(
        f"Min latency:    "
        f"{successful_latencies.min():.2f} ms"
    )

    print(
        f"Max latency:    "
        f"{successful_latencies.max():.2f} ms"
    )

    print("=" * 60)

else:

    print(
        "No successful API requests."
    )